use verus::prelude::*;

/// Checks whether three piles of lamps (r, g, b) can be arranged so that
/// no two adjacent lamps have the same color.  Equivalently,
/// 2*max(r,g,b) ≤ (r+g+b)+1 is the necessary and sufficient condition.
///
/// We require that the inputs be nonnegative; beyond that the function
/// returns `true` exactly when the feasibility inequality holds.
#[requires(r >= 0 && g >= 0 && b >= 0)]
#[ensures(
    // The function result is true exactly when 2*max_count ≤ total + 1
    result == (
        2 * (r as i16).max(g as i16).max(b as i16)
        <= (r as i16 + g as i16 + b as i16) + 1
    )
)]
pub fn check_lamp_arrangement(r: i8, g: i8, b: i8) -> bool {
    // To avoid any potential overflow in i8 arithmetic, promote to a larger integer type.
    let r = r as i16;
    let g = g as i16;
    let b = b as i16;

    let max_count = r.max(g).max(b);
    let total = r + g + b;

    // Feasibility condition: twice the largest pile ≤ sum of all piles + 1
    2 * max_count <= total + 1
}

